/*
 * @file 中文文件头生成（FR-11）
 * @description 所有生成文件自动写入中文文件头注释块：@file / @description / @author / @created /
 *   @since / @generated by @fw/cli。作者取 git config user.name，未配置时回退仓库默认署名并告警，
 *   绝不生成空作者。格式与 scripts/check-file-headers.mjs 的门禁一致（ts/js 块注释、vue HTML 注释）。
 * @author donttemo
 * @created 2026-10-13
 * @module cli/gen
 */

/** 仓库统一默认署名（git 未配置 user.name 时回退） */
export const DEFAULT_AUTHOR = 'donttemo';

/** 文件头参数 */
export interface HeaderOptions {
  /** 文件名（不含目录） */
  file: string;
  /** 中文描述（模板提供） */
  description: string;
  /** 模块名（@module） */
  moduleName: string;
  /** 作者 */
  author: string;
  /** 创建日期 YYYY-MM-DD */
  created: string;
  /** 框架版本（@since） */
  since?: string;
}

/** 生成文件头注释块（不含后续空行，由调用方拼接） */
export function buildFileHeader(options: HeaderOptions): string {
  const { file, description, moduleName, author, created } = options;
  const since = options.since ?? 'v0.1.0';
  const body = [
    ` * @file ${file}`,
    ` * @description ${description}`,
    ` * @author ${author}`,
    ` * @created ${created}`,
    ` * @module ${moduleName}`,
    ` * @since ${since}`,
    ' * @generated by @fw/cli gen crud —— 本文件由代码生成器产出；业务扩展请勿直接修改，',
    ' *   改用继承 / 钩子或在项目 templates/codegen/ 覆盖模板后重生成（--force 才会覆盖本文件）',
  ].join('\n');

  if (file.endsWith('.vue')) return `<!--\n${body}\n-->\n`;
  if (file.endsWith('.sql')) {
    return [
      `-- @file ${file}`,
      `-- @description ${description}`,
      `-- @author ${author}`,
      `-- @created ${created}`,
      `-- @generated by @fw/cli gen crud`,
      '',
    ].join('\n');
  }
  return `/*\n${body}\n */\n`;
}

/** 取当天日期（本地时区 YYYY-MM-DD，供测试注入） */
export function today(now: Date = new Date()): string {
  const pad = (value: number): string => String(value).padStart(2, '0');
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}
